import java.util.*;

class Solution {
    private static class Node {
        Node[] next = new Node[26];
        boolean isEnd;
    }

    public String shortenWords(String[] roots, String sentence) {
        Node root = new Node();
        for (String r : roots) {
            Node cur = root;
            for (char c : r.toCharArray()) {
                int k = c - 'a';
                if (cur.next[k] == null) cur.next[k] = new Node();
                cur = cur.next[k];
            }
            cur.isEnd = true;
        }
        StringBuilder sb = new StringBuilder();
        for (String w : sentence.split(" ")) {
            if (sb.length() > 0) sb.append(' ');
            Node cur = root;
            int cut = -1;                       // length of the shortest root found
            for (int i = 0; i < w.length(); i++) {
                cur = cur.next[w.charAt(i) - 'a'];
                if (cur == null) break;          // no root continues this way
                if (cur.isEnd) { cut = i + 1; break; } // first root end = shortest root
            }
            sb.append(cut == -1 ? w : w.substring(0, cut));
        }
        return sb.toString();
    }
}

