class Solution:
    def shortenWords(self, roots: List[str], sentence: str) -> str:
        t = {}
        for r in roots:
            n = t
            for c in r: n = n.setdefault(c, {})
            n["$"] = r
        out = []
        for w in sentence.split(" "):
            n, rep = t, w
            for c in w:
                if c not in n: break
                n = n[c]
                if "$" in n: rep = n["$"]; break
            out.append(rep)
        return " ".join(out)

