function shortenWords(roots, sentence) {
  const rs = new Set(roots);
  return sentence.split(" ").map(w => { for (let i = 1; i <= w.length; i++) if (rs.has(w.slice(0, i))) return w.slice(0, i); return w; }).join(" ");
}
